-- Dark Portal defenders: individual reinforcement paths and combat behavior.
-- Spawn positions and paths adapted from Gultask's retail sniff, client build 68887:
-- https://gist.github.com/Gultask/64095dbf93f4d8ad986622a819844b40
-- Gist revision: 1dbb9885f06bd93cfe985679b91fbfd60f9690a2.
-- Reuse the existing defender GUIDs for the 36 sniffed soldiers (18 per faction).
-- Keep the existing respawn times, demon routes, phase masks and wave intervals.

-- Keep entry-level combat SAI alongside each spawn's individual path starter.
UPDATE `creature_template` SET `flags_extra` = 134217728 WHERE `entry` IN (18948, 18949, 18950, 18965, 18970, 18971, 18972, 18986);
UPDATE `creature_template` SET `unit_flags` = 33024 WHERE `entry` IN (18949, 18971);

-- Only the two Hellfire targets should hover. Leave the six Hyjal targets unchanged.
DELETE FROM `creature_movement_override` WHERE `SpawnId` IN (74081, 74082);

-- The final waypoint is each defender's post; marker-led formations are no longer needed.
DELETE FROM `creature_formations` WHERE `leaderGUID` BETWEEN 68587 AND 68624;

DELETE FROM `creature` WHERE `guid` IN (68010, 68011, 68012, 68013, 68015, 68016, 68017, 68018, 68020, 68021, 68022, 68023, 68024, 68025, 68111, 68112, 68113, 68114, 68115, 68116, 68122, 68123, 68124, 68125, 68126, 68127, 68128, 68262, 68263, 68264, 68265, 68266, 86066, 86068, 86069, 86070, 86071) AND `id` IN (18948, 18949, 18950, 18965, 18970, 18971, 18972, 18986);

