-- Totems need their passive spell as well as the commander's summon spell.
DELETE FROM `creature_template_spell` WHERE `CreatureID` IN (19222, 19225) AND `Index` = 0;

-- Justinius uses Consecration Rank 3 (20922) while fighting demons.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 22 AND `SourceEntry` = 18966 AND `SourceGroup` = 75;

-- Greater Blessing of Might should buff NPC allies, not players.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` = 29381;
